"""Independent slow reference implementation of PROTOCOL.md for cross-checking."""
import itertools, json
from decimal import Decimal, getcontext
from fractions import Fraction
getcontext().prec = 80

PAD = 1514

def real_len(values):
    for i, v in enumerate(values):
        if v == PAD: return i
    return len(values)

def ref_fragments(rows, width):
    frags = []
    for ri, row in enumerate(rows):
        values, act = row['values'], row['activation']
        n = real_len(values)
        if n == 0: continue
        a = act[:n]
        mean = Decimal(sum(a))/Decimal(n)
        std = (sum((Decimal(x)-mean)**2 for x in a)/Decimal(n)).sqrt()
        thr = mean + std
        high = [x > thr for x in a]
        j = 0
        while j < n:
            if not high[j]: j += 1; continue
            s = j
            while j < n and high[j]: j += 1
            L = j - s
            if L < 2: continue
            if L <= width:
                frags.append((ri, s, L, row['class'], tuple(values[s:s+L])))
            else:
                best = None
                for p in range(s, s+L-width+1):
                    t = sum(a[p:p+width])
                    if best is None or t > best[0]: best = (t, p)
                frags.append((ri, best[1], width, row['class'], tuple(values[best[1]:best[1]+width])))
    return frags

def ref_interval(seqs):
    n = len(seqs); L = len(seqs[0]); out = []
    for i in range(L):
        col = [s[i] for s in seqs]
        lo, hi = min(col), max(col)
        mean = Decimal(sum(col))/Decimal(n)
        sigma = (sum((Decimal(v)-mean)**2 for v in col)/Decimal(n)).sqrt()
        d1 = Decimal(lo)-sigma; d2 = Decimal(hi)+sigma
        lo_t = int(d1.to_integral_value(rounding='ROUND_DOWN')) if d1 >= 0 else int(d1.to_integral_value(rounding='ROUND_UP'))
        out.append((max(0, lo_t), min(3028, int(d2.to_integral_value(rounding='ROUND_DOWN')))))
    return out

def ref_dist_leq(a, b, p, q):
    L = len(a); S = 0; A = 0
    for x, y in zip(a, b):
        d = abs(x-y)
        if (x < 1514 < y) or (y < 1514 < x): d += 1000
        S += d*d
        if x == y: A += 1
    return S*(9**A)*q*q <= L*(25**A)*p*p

def ref_clusters(frags, eps, ratio):
    p, q = eps; rp, rq = ratio
    groups = {}; counts = {}
    for fid, f in enumerate(frags):
        groups.setdefault((f[3], len(f[4])), []).append(fid)
        counts[f[3]] = counts.get(f[3], 0)+1
    clusters = []
    for (cls, L), fids in groups.items():
        m = counts[cls]
        dmin = max(2, -((-m*rp)//rq))
        n = len(fids)
        adj = [[i == j or ref_dist_leq(frags[fids[i]][4], frags[fids[j]][4], p, q)
                for j in range(n)] for i in range(n)]
        cores = [i for i in range(n) if sum(adj[i]) >= dmin]
        comp = {}; lab = 0; seen = set()
        for c in cores:
            if c in seen: continue
            stack = [c]; seen.add(c); grp = []
            while stack:
                cur = stack.pop(); grp.append(cur)
                for o in cores:
                    if o not in seen and adj[cur][o]: seen.add(o); stack.append(o)
            for g in grp: comp[g] = lab
            lab += 1
        cmin = {}
        for c, l in comp.items(): cmin[l] = min(cmin.get(l, 10**9), fids[c])
        l2i = {v: k for k, v in cmin.items()}
        here = {l: ([fids[c] for c in cores if comp[c] == l], cmin[l]) for l in cmin}
        for i in range(n):
            if i in cores: continue
            labs = {comp[j] for j in cores if adj[i][j]}
            if labs:
                here[l2i[min(cmin[l] for l in labs)]][0].append(fids[i])
        for l, (members, cid) in here.items():
            clusters.append({'id': cid, 'class': cls,
                             'members': sorted(members),
                             'core': sorted(fids[c] for c in cores if comp[c] == l),
                             'range': ref_interval([frags[f][4] for f in sorted(members)])})
    clusters.sort(key=lambda c: c['id'])
    noise = sorted(set(range(len(frags))) - {f for c in clusters for f in c['members']})
    return clusters, noise

def ref_match_window(prefix, pattern):
    L = len(pattern)
    for s in range(0, len(prefix)-L+1):
        if all(lo <= prefix[s+i] <= hi for i, (lo, hi) in enumerate(pattern)):
            return True
    return False

def ref_exact_entries(patterns, limit):
    keys = set()
    for pat in patterns:
        coords = [[v for v in range(lo, hi+1) if v != PAD] for lo, hi in pat]
        if any(not c for c in coords): continue
        for combo in itertools.product(*coords):
            keys.add((len(pat), combo))
    return min(len(keys), limit)

def ref_release(spec, capacity):
    width = spec['width']; classes = spec['classes']
    frags = ref_fragments(spec['discovery'], width)
    clusters, noise = ref_clusters(frags, spec['eps'], spec['ratio'])
    prefixes = [row['values'][:real_len(row['values'])] for row in spec['validation']]
    counts = [0]*classes
    for row in spec['validation']: counts[row['class']] += 1
    for c in clusters:
        hits = [0]*classes
        for ri, pre in enumerate(prefixes):
            if ref_match_window(pre, c['range']):
                hits[spec['validation'][ri]['class']] += 1
        t = c['class']
        cin = Fraction(hits[t], counts[t]) if counts[t] else Fraction(0)
        others = [Fraction(hits[x], counts[x]) for x in range(classes) if x != t and counts[x]]
        cout = max(others) if others else Fraction(0)
        c['hits'] = hits
        c['score'] = cin/(cout + Fraction(1, 10000))
        c['kept'] = c['score'] > Fraction(spec['threshold'][0], spec['threshold'][1])
    kept = sorted([c for c in clusters if c['kept']], key=lambda c: (-c['score'], c['id']))
    if spec['mode'] == 'range':
        entries = len(kept)
    else:
        entries = ref_exact_entries([c['range'] for c in kept], capacity['exact']+1)
    # backup: same pinned sklearn path
    sys_path = None
    import numpy as np
    from sklearn.tree import DecisionTreeClassifier
    X = np.array([[r['values'][:width] + [PAD]*(width-len(r['values'][:width]))] [0] for r in spec['train']], dtype=np.int32)
    y = np.array([r['class'] for r in spec['train']])
    model = DecisionTreeClassifier(max_depth=10, random_state=42, class_weight='balanced')
    model.fit(X, y)
    tr = model.tree_; classes_ = [int(v) for v in model.classes_]
    nodes = []
    for i in range(tr.node_count):
        if tr.children_left[i] == -1:
            nodes.append([classes_[int(np.argmax(tr.value[i][0]))]])
        else:
            nodes.append([int(tr.feature[i]), int(round(2*float(tr.threshold[i]))),
                          int(tr.children_left[i]), int(tr.children_right[i])])
    def predict(feats):
        node = nodes[0]
        while len(node) == 4:
            f, thr, l, r = node
            node = nodes[l if 2*feats[f] <= thr else r]
        return node[0]
    item = {'id': spec['id'],
            'fragments': [[f[0], f[1], f[2]] for f in frags],
            'noise': noise,
            'clusters': [{'id': c['id'], 'class': c['class'], 'members': c['members'],
                          'core': c['core'],
                          'range': [[lo, hi] for lo, hi in c['range']],
                          'hits': c['hits'],
                          'score': [c['score'].numerator, c['score'].denominator],
                          'kept': c['kept']} for c in clusters],
            'priority': [c['id'] for c in kept],
            'backup': nodes, 'entries': entries}
    return item, {'id': spec['id'], 'mode': spec['mode'], 'entries': entries,
                  'width': width, 'packet_limit': spec['packet_limit'],
                  'idle_us': spec['idle_us'], 'predict': predict,
                  'patterns': [(c['id'], c['class'], len(c['range']), c['range']) for c in kept]}

def ref_execute(request):
    from online_matching.train_rf import backup_predict  # not used; local predict
    capacity = request['capacity']
    catalog = []; models = {}
    for spec in request['releases']:
        item, model = ref_release(spec, capacity)
        catalog.append(item); models[spec['id']] = model
    current = None; residents = {}; pins = {}; active = {}; opened = {}
    installs = []; decisions = []
    def used():
        return {'range': sum(v for k, v in residents.items() if models[k]['mode'] == 'range'),
                'exact': sum(v for k, v in residents.items() if models[k]['mode'] == 'exact')}
    at = 0
    for block in request['blocks']:
        for ev in block:
            op = ev[0]
            if op == 'install':
                rid = ev[1]; m = models[rid]
                if m['entries'] > capacity[m['mode']]: status = 'oversize'
                else:
                    pros = dict(residents)
                    if current is not None and current != rid and pins.get(current, 0) == 0:
                        del pros[current]
                    pros[rid] = m['entries']
                    ru = sum(v for k, v in pros.items() if models[k]['mode'] == 'range')
                    eu = sum(v for k, v in pros.items() if models[k]['mode'] == 'exact')
                    if ru > capacity['range'] or eu > capacity['exact']: status = 'busy'
                    else:
                        status = 'ok'; residents = pros; current = rid
                installs.append({'at': at, 'id': rid, 'status': status,
                                 'resident': sorted(residents), 'used': used()})
            elif op == 'open':
                fid = ev[1]
                if fid in active or current is None: return {'error': 'invalid_request'}
                ep = {'flow': fid, 'epoch': opened.get(fid, 0), 'release': current,
                      'm': models[current], 'feats': [], 'consumed': 0, 'dir': None,
                      'last': None, 'committed': False}
                opened[fid] = ep['epoch']+1
                active[fid] = ep
                pins[current] = pins.get(current, 0)+1
            elif op == 'packet':
                fid, ts, src, length = ev[1], ev[2], ev[3], ev[4]
                ep = active.get(fid)
                if ep is None: return {'error': 'invalid_request'}
                if ep['last'] is not None and ts < ep['last']: return {'error': 'invalid_request'}
                m = ep['m']
                if ep['dir'] is None: ep['dir'] = src
                enc = 1514+length if src == ep['dir'] else 1514-length
                gap = None if ep['last'] is None else ts-ep['last']
                ep['last'] = ts
                if ep['committed']: at += 1; continue
                if ep['consumed'] >= m['width'] and gap is not None and gap > m['idle_us']:
                    w = m['width']
                    feats = ep['feats'][:w] + [PAD]*(w-len(ep['feats'][:w]))
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': m['predict'](feats),
                                      'reason': 'idle', 'rule': None, 'start': None})
                    ep['committed'] = True; at += 1; continue
                ep['feats'].append(enc); ep['consumed'] += 1
                best = None
                for (cid, cls, L, pattern) in m['patterns']:
                    if ep['consumed'] >= L and ref_match_window(ep['feats'][ep['consumed']-L:], pattern):
                        best = (cid, cls, L); break
                if best is not None:
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': best[1],
                                      'reason': 'segment', 'rule': best[0],
                                      'start': ep['consumed']-best[2]})
                    ep['committed'] = True; at += 1; continue
                if ep['consumed'] > m['packet_limit']:
                    w = m['width']
                    feats = ep['feats'][:w] + [PAD]*(w-len(ep['feats'][:w]))
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': m['predict'](feats),
                                      'reason': 'limit', 'rule': None, 'start': None})
                    ep['committed'] = True; at += 1; continue
            else:
                fid = ev[1]; ep = active.pop(fid, None)
                if ep is None: return {'error': 'invalid_request'}
                if not ep['committed']:
                    w = ep['m']['width']
                    feats = ep['feats'][:w] + [PAD]*(w-len(ep['feats'][:w]))
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': ep['m']['predict'](feats),
                                      'reason': 'close', 'rule': None, 'start': None})
                r = ep['release']
                left = pins.get(r, 0)-1
                if left > 0: pins[r] = left
                else:
                    pins.pop(r, None)
                    if current != r: residents.pop(r, None)
            at += 1
    if active: return {'error': 'invalid_request'}
    return {'catalog': catalog, 'installs': installs, 'decisions': decisions,
            'final': {'current': current, 'resident': sorted(residents), 'used': used()}}
